// Helper to get icon by name
pub fn get_icon(name: &str) -> &'static str {
    match name {
        "overview" => ICON_OVERVIEW,
        "agents" => ICON_AGENTS,
        "memory" => ICON_MEMORY,
        "monitor" => ICON_MONITOR,
        "actionlog" => ICON_ACTIONLOG,
        "books" => ICON_BOOKS,
        "history" => ICON_HISTORY,
        "prompts" => ICON_PROMPTS,
        "experiments" => ICON_EXPERIMENTS,
        "insights" => ICON_INSIGHTS,
        "notebook" => ICON_NOTEBOOK,
        "pipeline" => ICON_PIPELINE,
        "trust" => ICON_TRUST,
        "compliance" => ICON_COMPLIANCE,
        "safety" => ICON_SAFETY,
        "firewall" => ICON_FIREWALL,
        "disputes" => ICON_DISPUTES,
        "tools" => ICON_TOOLS,
        "protocols" => ICON_PROTOCOLS,
        "multiagent" => ICON_MULTIAGENT,
        "infra" => ICON_INFRA,
        "orchestrator" => ICON_ORCHESTRATOR,
        "secrets" => ICON_SECRETS,
        "grounding" => ICON_GROUNDING,
        "context" => ICON_CONTEXT,
        "webhooks" => ICON_WEBHOOKS,
        "notifications" => ICON_NOTIFICATIONS,
        "economy" => ICON_ECONOMY,
        "marketplace" => ICON_MARKETPLACE,
        "verify" => ICON_VERIFY,
        "debug" => ICON_DEBUG,
        "billing" => ICON_BILLING,
        "license" => ICON_LICENSE,
        "settings" => ICON_SETTINGS,
        "logout" => ICON_LOGOUT,
        "user" => ICON_USER,
        "folder" => ICON_FOLDER,
        "search" => ICON_SEARCH,
        "plus" => ICON_PLUS,
        "check" => ICON_CHECK,
        "x" => ICON_X,
        "cpu" => ICON_CPU,
        "database" => ICON_DATABASE,
        "zap" => ICON_ZAPP,
        "activity" => ICON_ACTIVITY,
        _ => ICON_FOLDER,
    }
}
